'use strict';
// Browser rendering of the real PGlite snapshots generated by side_three_cycles_db.cjs.
const {chromium}=require('playwright'),{execFileSync}=require('node:child_process');
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'..'),out=path.join(root,'reports/evidencia_ventas_2026-10-28');
const rows=JSON.parse(fs.readFileSync(path.join(out,'snapshots.json'),'utf8'));
const model=rows.filter(r=>r.empresa_id===rows[0].empresa_id).map(r=>({round:r.ciclo,closureStatus:'closed',cycleReceipt:r.estado_resultados.cycleReceipt,estadoResultados:r.estado_resultados,balanceCaja:r.balance_caja,flujoCaja:r.flujo_caja,balanceGeneral:r.estado_resultados.balanceGeneral||{}}));
const all=[...new Set(rows.map(r=>r.empresa_id))].map(id=>{const history=rows.filter(r=>r.empresa_id===id).map(r=>({round:r.ciclo,closureStatus:'closed',cycleReceipt:r.estado_resultados.cycleReceipt,estadoResultados:r.estado_resultados,balanceCaja:r.balance_caja,flujoCaja:r.flujo_caja,balanceGeneral:r.estado_resultados.balanceGeneral||{}}));const last=history.at(-1),record=rows.filter(r=>r.empresa_id===id).at(-1);return {id:String(id),empresaId:id,empresa:'TEST-20261028-'+id,nombre:'Prueba local',ronda:last.round,estado:'activa',cycleHistory:history,cycleReceipt:last.cycleReceipt,estadoResultados:last.estadoResultados,balanceCaja:last.balanceCaja,flujoCaja:last.flujoCaja,balanceGeneral:last.balanceGeneral,ingresos:Number(record.ingresos),costos:Number(record.costos),utilidad:Number(record.utilidad),caja:Number(record.caja_final)};});
function doc(name){return execFileSync('python',['-B','-c',`import sys;sys.path.insert(0,'tests');from browser_fixture import document;print(document('${name}'))`],{cwd:root,encoding:'utf8',maxBuffer:100*1024*1024,env:{...process.env,PYTHONUTF8:'1'}})}
(async()=>{const browser=await chromium.launch({headless:true,executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe'});try{
 for(const viewport of [{width:1366,height:900},{width:390,height:844}]){
  const suffix=viewport.width>500?'desktop':'movil';
  const page=await browser.newPage({viewport,locale:'es-PE'});await page.route('**/*',r=>r.abort());
  await page.setContent(doc('index.html'),{waitUntil:'load'});
  await page.evaluate(history=>{document.querySelectorAll('.screen').forEach(e=>e.classList.add('hidden'));document.getElementById('studentLobby').classList.remove('hidden');document.getElementById('studentCycleHistory').innerHTML=SIDE_STUDENT_FINANCIAL_VIEW.summaryHtml({history},true);},model);
  const student=page.locator('#studentCycleHistory');await student.scrollIntoViewIfNeeded();assert.match(await student.innerText(),/Ingresos acumulados/);assert.match(await student.innerText(),/Vendidas/);await page.screenshot({path:path.join(out,`estudiante-${suffix}.png`)});await page.close();
  const teacher=await browser.newPage({viewport,locale:'es-PE'});await teacher.route('**/*',r=>r.abort());await teacher.setContent(doc('docente.html'),{waitUntil:'load'});await teacher.waitForFunction(()=>!reportsBusy);
  await teacher.evaluate(reports=>{[teacherPoll,teacherTick,companiesPoll].forEach(clearInterval);clearTimeout(companiesRefresh);switchTab('resultados');state.partidaId='local-test';state.reports=reports;state.resultCompanyId=reports[0].id;renderResults();},all);
  assert.match(await teacher.locator('#detailReports').innerText(),/Vendidas/);assert.match(await teacher.locator('#resultComparison').innerText(),/Ingresos/);await teacher.locator('#tab-resultados').screenshot({path:path.join(out,`docente-${suffix}.png`)});await teacher.close();
 }
 console.log('Capturas generadas desde snapshots PGlite guardados.');
 }finally{await browser.close()}})().catch(e=>{console.error(e);process.exitCode=1});


